class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        ans = []
        m, n = len(grid), len(grid[0])
        i, j = 0, 0

        while i < m and j < n:
            ans.append(grid[i][j])

            # Move right if possible
            if j + 1 < n and not (i % 2 == 0 and j + 1 == n):
                j += 1
            else:
                # If cannot move right, move down
                i += 1

            # Move left if possible
            if j - 1 >= 0 and not (i % 2 == 0 and j - 1 == 0):
                j -= 1
            else:
                # If cannot move left, move down
                i += 1

        return ans

def rank_people(n, scores):
    ranks = [None] * n
    max_score = -float('inf')
    count_max_score = 0

    for i in range(n):
        if scores[i] > max_score:
            max_score = scores[i]
            count_max_score = 1
        elif scores[i] == max_score:
            count_max_score += 1

    current_rank = 1
    for i in range(n):
        if ranks[i] is None:
            ranks[i] = current_rank
            current_rank += count_max_score

    return ranks

