import sys

def has_matching_subsequences(A, B):
    # Create a dictionary to store the frequency of each element in A
    freq_A = {}
    for num in A:
        if num in freq_A:
            freq_A[num] += 1
        else:
            freq_A[num] = 1

    # Iterate through each element in B
    for num in B:
        # If the element is in A, check its frequency
        if num in freq_A:
            freq_A[num] -= 1
            if freq_A[num] == 0:
                del freq_A[num]

        # If the element is not in A, return False
        if num not in freq_A:
            return False

    # If all elements in B have been found in A, return True
    return True

