def check_block_exists(N, W, X, Y, Q, T, A):
    # Create a list to represent the grid
    grid = [[0] * W for _ in range(N)]

    # Place the blocks initially
    for x, y in zip(X, Y):
        grid[y - 1][x - 1] = 1

    # Move the blocks
    for t in range(1, 10**101):
        if all(grid[-1]):
            break

        for y in range(N - 2, -1, -1):
            for x in range(W):
                if grid[y][x] == 1 and (y == N - 2 or grid[y + 1][x] == 0):
                    grid[y][x] = 0

    # Check if block A exists at time T+0.5
    return 'Yes' if grid[T % N][A - 1] else 'No'

