class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == n:
            return sum(nums) % (10**9+7)

        # Sort the numbers in ascending order
        nums.sort()

        # Calculate the sum of the first k elements
        s = sum(nums[:k])

        # Calculate the sum of the last k elements
        s += sum(nums[n-k:])

        # Return the sum modulo 10^9 + 7
        return s % (10**9+7)

def check_geometric_progression(sequence):
    if len(sequence) < 2:
        return "Yes"  # A sequence with less than 2 elements is trivially a geometric progression

    common_ratio = sequence[1] / sequence[0]

    for i in range(2, len(sequence)):
        if sequence[i] / sequence[i - 1] != common_ratio:
            return "No"

    return "Yes"

