def check_sortability(A):
    # Check if the list is already sorted
    if A == sorted(A):
        return "No"

    # Find the first pair where the current element is greater than the next element
    for i in range(len(A) - 1):
        if A[i] > A[i + 1]:
            # Check if swapping this pair would sort the list
            if A[:i] + [A[i + 1], A[i]] + A[i + 2:] == sorted(A):
                return "Yes"
            else:
                return "No"

    # If no such pair is found, the list cannot be sorted by one swap
    return "No"

